    pdf_chrome_settings_highlight_notes_desc: "ଯେତେବେଳେ ସକ୍ରିୟ ହୁଏ, PDF ପରି ସମାନ ନାମ ଥିବା Markdown ନୋଟରେ ନୂତନ ବିଶେଷତ୍ୱଗୁଡ଼ିକୁ ସଂଯୁକ୍ତ କରାଯାଇଥାଏ । ସଂଯୋଗିତ ଅଂଶଗୁଡ଼ିକ ସ୍ୱୟଂଚାଳିତ ଭାବରେ ଯୋଗ କରାଯାଇଥାଏ; ଯଦି ଏହା ଅବସ୍ଥିତ ନାହିଁ ତେବେ ଟିପ୍ପଣୀଟି ନିର୍ମାଣ କରାଯାଇଥାଏ ।",
